import random

def make_question(question, options, answer, explanation, difficulty, topic, hint):
    return dict(question=question, options=options, answer=answer, explanation=explanation, difficulty=difficulty, topic=topic, hint=hint)

QUESTION_BANK = {}
def add(cat, level, topic, q, a, wrong, explanation, hint):
    QUESTION_BANK.setdefault(cat, []).append(make_question(q, [a]+wrong, a, explanation, level, topic, hint))

# Numeric practice questions generated from exact arithmetic.
for i in range(1,11):
    n=100+20*i; a=n//5
    add('Quantitative Aptitude','Easy','Percentages',f'What is 20% of {n}?',str(a),[str(a+5),str(a-5),str(a+10)],f'{n} × 20 / 100 = {a}.','Divide the number by five.')
    c=100*i; p=10+5*i; s=c*(100+p)//100
    add('Quantitative Aptitude','Medium','Profit and Loss',f'An item costs Rs. {c} and sells for Rs. {s}. Find the profit percentage.',f'{p}%',[f'{p+5}%',f'{p-5}%',f'{p+10}%'],f'Profit percentage = ({s}-{c})/{c} × 100 = {p}%.','Divide profit by cost price.')
    d=3*i; e=6*i; a=2*i
    add('Quantitative Aptitude','Hard','Time and Work',f'A completes a task in {d} days and B in {e} days. How long together?',f'{a} days',[f'{a+1} days',f'{a+2} days',f'{d+e} days'],f'Combined rate = 1/{d} + 1/{e} = 1/{a}.','Add daily work rates, then invert.')
    a=3*i+12
    add('Logical Reasoning','Easy','Number Series',f'Find the next term: {3*i}, {3*i+3}, {3*i+6}, {3*i+9}, ?',str(a),[str(a+1),str(a-1),str(a+3)],'Each term increases by 3.','Check consecutive differences.')
    word=['CAT','DOG','PEN','BOOK','FISH','BIRD','TREE','LION','GOAT','MILK'][i-1]
    shift=lambda w,k: ''.join(chr((ord(c)-65+k)%26+65) for c in w)
    add('Logical Reasoning','Medium','Coding-Decoding',f'If ABC becomes CDE, how is {word} encoded?',shift(word,2),[shift(word,1),shift(word,3),word],'Shift every letter forward by two.','Compare ABC with CDE.')
    seq=[i+j*j for j in range(1,5)]; a=i+25
    add('Logical Reasoning','Hard','Number Patterns',f'Find the next term: {", ".join(map(str,seq))}, ?',str(a),[str(a-1),str(a+1),str(a+3)],'Differences are 3, 5, 7, then 9.','Look at the differences between terms.')

